"use strict";const e=require("./request.js");exports.adminCheck=function(){return e.get("/admin/recipes/check")},exports.adminFeedbackList=function(t={}){return e.get("/admin/feedback",t)},exports.adminFeedbackSetStatus=function(t,n){return e.put(`/admin/feedback/${t}/status`,{status:n})},exports.adminGetGenerationConfig=function(){return e.get("/admin/recipes/generation-config")},exports.adminRecipeBatchImage=function(t){return e.post("/admin/recipes/batch-image",{count:t})},exports.adminRecipeBatchSetImage=function(t){return e.post("/admin/recipes/batch-set-image",{items:t})},exports.adminRecipeDelete=function(t){return e.del(`/admin/recipes/${t}`)},exports.adminRecipeDetail=function(t){return e.get(`/admin/recipes/${t}`)},exports.adminRecipeGenImage=function(t,n=!1){return e.post(`/admin/recipes/${t}/image${n?"?force=true":""}`,{})},exports.adminRecipeList=function(t){return e.get("/admin/recipes",t)},exports.adminRecipeSetImage=function(t,n){return e.post(`/admin/recipes/${t}/set-image`,{imageUrl:n})},exports.adminRecipeStats=function(){return e.get("/admin/recipes/stats")},exports.adminRecipeUpdate=function(t,n){return e.put(`/admin/recipes/${t}`,n)},exports.adminRunGenerationNow=function(t){return e.post("/admin/recipes/generation-run",{count:t})},exports.adminUpdateGenerationConfig=function(t){return e.put("/admin/recipes/generation-config",t)};
